SELECT c.*, m.model_name, m.model_brand, p.parking_name FROM car c JOIN model m ON c.model_id = m.model_id JOIN parking p ON c.rental_station = p.parking_id
AND (m.model_name LIKE CONCAT('%', #{keyword}, '%') OR m.model_brand LIKE CONCAT('%', #{keyword}, '%'))
AND c.car_status = #{status}
ORDER BY c.car_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM car c JOIN model m ON c.model_id = m.model_id
AND (m.model_name LIKE CONCAT('%', #{keyword}, '%') OR m.model_brand LIKE CONCAT('%', #{keyword}, '%'))
AND c.car_status = #{status}

